  "inlineSchema": "// ============================================================================\n// Prisma schema — Portfolio dinamis\n// Provider: PostgreSQL. Jalankan `pnpm db:generate` setelah mengubah file ini.\n// ============================================================================\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"./generated\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ---------------------------------------------------------------------------\n// Kategori project — dipakai filter pada bagian Work.\n// ---------------------------------------------------------------------------\nenum ProjectCategory {\n  WEB\n  MOBILE\n  OSS\n}\n\n// ---------------------------------------------------------------------------\n// Profile (singleton, id selalu \"singleton\").\n// Menampung identitas + konfigurasi hero, about, dan kontak.\n// Kolom String[] mendukung array teks (Paragraf about, kata berputar hero).\n// ---------------------------------------------------------------------------\nmodel Profile {\n  id               String   @id @default(\"singleton\")\n  // Identitas\n  fullName         String\n  brand            String\n  role             String\n  // Hero\n  availabilityText String\n  heroLead         String\n  rotatingWords    String[]\n  photoUrl         String\n  photoTagline     String\n  // About\n  aboutNote        String\n  aboutParagraphs  String[]\n  badgeValue       String\n  badgeLabel       String\n  // Contact\n  contactSubtitle  String\n  contactEmail     String\n  contactCallUrl   String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ---------------------------------------------------------------------------\n// Statistik hero (counter angka + suffix).\n// ---------------------------------------------------------------------------\nmodel Stat {\n  id     String @id @default(cuid())\n  value  Int\n  suffix String @default(\"\")\n  label  String\n  order  Int    @default(0)\n\n  @@index([order])\n}\n\n// ---------------------------------------------------------------------------\n// Daftar layanan (bagian Services).\n// ---------------------------------------------------------------------------\nmodel Service {\n  id          String @id @default(cuid())\n  name        String @unique\n  description String\n  order       Int    @default(0)\n\n  @@index([order])\n}\n\n// ---------------------------------------------------------------------------\n// Tech stack: grup (Frontend/Backend/...) berisi banyak item.\n// ---------------------------------------------------------------------------\nmodel StackGroup {\n  id    String      @id @default(cuid())\n  title String      @unique\n  order Int         @default(0)\n  items StackItem[]\n\n  @@index([order])\n}\n\nmodel StackItem {\n  id      String     @id @default(cuid())\n  name    String\n  order   Int        @default(0)\n  groupId String\n  group   StackGroup @relation(fields: [groupId], references: [id], onDelete: Cascade)\n\n  @@unique([groupId, name])\n  @@index([order])\n}\n\n// ---------------------------------------------------------------------------\n// Project portfolio + tag-nya.\n// ---------------------------------------------------------------------------\nmodel Project {\n  id          String          @id @default(cuid())\n  slug        String          @unique\n  title       String\n  description String\n  category    ProjectCategory\n  year        Int\n  imageUrl    String\n  href        String?\n  featured    Boolean         @default(false)\n  order       Int             @default(0)\n  tags        ProjectTag[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([category, year])\n}\n\nmodel ProjectTag {\n  id        String  @id @default(cuid())\n  name      String\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@unique([projectId, name])\n}\n\n// ---------------------------------------------------------------------------\n// Pengalaman karier (timeline) + poin-poin pendukung.\n// ---------------------------------------------------------------------------\nmodel Experience {\n  id          String            @id @default(cuid())\n  role        String\n  dateLabel   String\n  company     String\n  description String\n  order       Int               @default(0)\n  points      ExperiencePoint[]\n\n  @@index([order])\n}\n\nmodel ExperiencePoint {\n  id           String     @id @default(cuid())\n  text         String\n  order        Int        @default(0)\n  experienceId String\n  experience   Experience @relation(fields: [experienceId], references: [id], onDelete: Cascade)\n\n  @@index([order])\n}\n\n// ---------------------------------------------------------------------------\n// Testimonial / quote client (biasanya hanya satu yang tampil).\n// ---------------------------------------------------------------------------\nmodel Testimonial {\n  id          String  @id @default(cuid())\n  quote       String\n  authorName  String\n  authorRole  String\n  authorImage String\n  active      Boolean @default(true)\n  order       Int     @default(0)\n\n  @@index([active, order])\n}\n\n// ---------------------------------------------------------------------------\n// Fakta singkat pada bagian About (Based in, Timezone, ...).\n// Kolom `value` boleh memuat **penekanan** untuk frasa yang ditonjolkan.\n// ---------------------------------------------------------------------------\nmodel AboutFact {\n  id    String @id @default(cuid())\n  term  String @unique\n  value String\n  order Int    @default(0)\n\n  @@index([order])\n}\n\n// ---------------------------------------------------------------------------\n// Kartu informasi kontak (Availability / Based in / Response time).\n// `value` memuat kalimat lengkap, frasa penting dibungkus ** **.\n// ---------------------------------------------------------------------------\nmodel ContactCard {\n  id    String @id @default(cuid())\n  key   String @unique\n  // Kalimat lengkap; frasa penting dibungkus ** ** agar di-highlight.\n  value String\n  order Int    @default(0)\n\n  @@index([order])\n}\n\n// ---------------------------------------------------------------------------\n// Tautan sosial media.\n// ---------------------------------------------------------------------------\nmodel SocialLink {\n  id    String @id @default(cuid())\n  label String @unique\n  url   String\n  order Int    @default(0)\n\n  @@index([order])\n}\n",
